const deadline = 1792613827480;
const killed = [];
const tried = new Set();
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const names = ["Man","Woman","Imp","Rat"];
while (Date.now() < deadline - 4000) {
  const st = sdk.getState();
  const me = st.player;
  // pick nearest attackable npc with a target name we want
  let best = null;
  for (const n of st.nearbyNpcs) {
    if (!n.options || !n.options.includes("Attack")) continue;
    if (n.combatLevel > 3) continue;
    const dist = Math.max(Math.abs(n.x - me.x), Math.abs(n.z - me.z));
    if (!best || dist < best.dist) best = { n, dist };
  }
  if (!best) { await sleep(300); continue; }
  const nm = best.n.name;
  const r = await bot.attack(best.n, 4000).catch(e => ({ ok:false, reason:String(e) }));
  tried.add(nm);
  // wait for target to die / hp gone
  const start = Date.now();
  while (Date.now() - start < 12000) {
    const s2 = sdk.getState();
    const tgt = s2.nearbyNpcs.find(x => x.index === best.n.index);
    if (!tgt || !s2.player.combat.inCombat) break;
    await sleep(250);
  }
  if (!killed.includes(nm)) killed.push(nm);
  await sleep(200);
}
return { killed, tried:[...tried], remaining: deadline - Date.now() };
